CREATE OR REPLACE FORCE EDITIONABLE VIEW "PPPT"."PERSONALESCOLARIDAD" ("IDPERSONAL", "GRADO", "ESCOLARIDAD", "IDESPECIALIDAD", "ESPECIALIDAD", "ESCUELA", "UBICACION", "SINO", "DE", "A", "TITULO", "ACTUAL") AS 
  SELECT Escolaridad.IdPersonal, Escolaridad.Grado, CatEscolaridad.Escolaridad, Escolaridad.Especialidad AS IdEspecialidad, CatEspecialidad.Especialidad, Escolaridad.Escuela, Escolaridad.Ubicacion, SiNo.SiNo, Escolaridad.De, Escolaridad.A, Escolaridad.Titulo, Escolaridad.Actual FROM (CatEspecialidad RIGHT JOIN (CatEscolaridad INNER JOIN Escolaridad ON CatEscolaridad.IdEscolaridad = Escolaridad.Grado) ON CatEspecialidad.IdEspecialidad = Escolaridad.Especialidad) INNER JOIN SiNo ON Escolaridad.Titulo = SiNo.IdSiNo;
